## Strategy con contexto

```javascript
class Compresor {
  #estrategia;

  constructor(estrategia) {
    this.#estrategia = estrategia;
  }

  setEstrategia(estrategia) {
    this.#estrategia = estrategia;
  }

  comprimir(datos) {
    return this.#estrategia(datos);
  }
}

const estrategias = {
  zip:  datos => ({ formato: 'zip',  tamanio: datos.length * 0.7 }),
  gzip: datos => ({ formato: 'gzip', tamanio: datos.length * 0.5 }),
  raw:  datos => ({ formato: 'raw',  tamanio: datos.length }),
};

const compresor = new Compresor(estrategias.gzip);
console.log(compresor.comprimir('archivo'.repeat(100)));
// { formato: 'gzip', tamanio: 350 }

compresor.setEstrategia(estrategias.zip);
console.log(compresor.comprimir('archivo'.repeat(100)));
// { formato: 'zip', tamanio: 490 }
```

