## Decorator como función de orden superior

En JS, decorar funciones es natural con HOFs:

```javascript
// Decorator de caché (memoize):
function conCache(fn) {
  const cache = new Map();
  return function(...args) {
    const clave = JSON.stringify(args);
    if (cache.has(clave)) return cache.get(clave);
    const resultado = fn.apply(this, args);
    cache.set(clave, resultado);
    return resultado;
  };
}

// Decorator de logging:
function conLog(fn, nombre = fn.name) {
  return function(...args) {
    console.log(`Llamando ${nombre}(${args.join(', ')})`);
    const resultado = fn.apply(this, args);
    console.log(`${nombre} retornó:`, resultado);
    return resultado;
  };
}

// Decorator de retry:
function conReintentos(fn, maxIntentos = 3) {
  return async function(...args) {
    for (let i = 0; i < maxIntentos; i++) {
      try {
        return await fn.apply(this, args);
      } catch (err) {
        if (i === maxIntentos - 1) throw err;
        console.log(`Intento ${i + 1} falló, reintentando...`);
      }
    }
  };
}

// Aplicar múltiples decorators:
const fetchConReintentos = conReintentos(conCache(fetch), 3);
```

