## Strategy vs Decorator

```
Strategy: elige UN algoritmo de varios posibles (uno a la vez)
  → ¿Cómo ordenar? ¿Cómo comprimir? ¿Cómo pagar?

Decorator: apila comportamientos sobre uno base
  → Función base + log + cache + retry + timeout
```

examples.code:
// Strategy: pipeline de formateo de precios
const formatos = {
  cop: precio => `$${precio.toLocaleString('es-CO')} COP`,
  usd: precio => `$${precio.toFixed(2)}`,
  eur: precio => `€${precio.toFixed(2)}`,
  compact: precio => precio >= 1000
    ? `$${(precio / 1000).toFixed(1)}k`
    : `$${precio}`,
};

function formatearPrecio(precio, estrategia) {
  if (!formatos[estrategia]) throw new Error(`Formato desconocido: ${estrategia}`);
  return formatos[estrategia](precio);
}

console.log(formatearPrecio(1234567, 'cop'));     // '$1.234.567 COP'
console.log(formatearPrecio(1234.56, 'usd'));     // '$1234.56'
console.log(formatearPrecio(1500, 'compact'));    // '$1.5k'

// Decorator: función con throttle + logging
function conThrottle(fn, ms) {
  let ultima = 0;
  return function(...args) {
    const ahora = Date.now();
    if (ahora - ultima < ms) return; // Ignora si muy frecuente
    ultima = ahora;
    return fn.apply(this, args);
  };
}

function conConteo(fn) {
  let llamadas = 0;
  const decorada = function(...args) {
    llamadas++;
    return fn.apply(this, args);
  };
  decorada.getLlamadas = () => llamadas;
  return decorada;
}

const manejarScroll = conConteo(
  conThrottle(
    (e) => console.log('Scroll procesado:', e),
    100
  )
);

// Simular múltiples llamadas rápidas:
const inicio = Date.now();
manejarScroll('evento1');
manejarScroll('evento2'); // Bloqueado por throttle
const llamadasTotales = manejarScroll.getLlamadas();
console.log('Llamadas totales (incluyendo bloqueadas):', llamadasTotales); // 2

