const estrategiasOrden = {
  asc:      (a, b) => a - b,
  desc:     (a, b) => b - a,
  longitud: (a, b) => a.length - b.length,
};

function ordenar(array, nombreEstrategia) {
  const estrategia = estrategiasOrden[nombreEstrategia];
  if (!estrategia) throw new Error(`Estrategia desconocida: ${nombreEstrategia}`);
  return [...array].sort(estrategia);
}

const r1 = ordenar([3, 1, 4, 1, 5, 9, 2], 'asc');
const r2 = ordenar([3, 1, 4, 1, 5, 9, 2], 'desc');
const r3 = ordenar(['banana', 'kiwi', 'manzana', 'higo'], 'longitud');

console.log(r1);
console.log(r2);
console.log(r3);

function conCache(fn) {
  const cache = new Map();

  function decorada(...args) {
    const clave = JSON.stringify(args);
    if (cache.has(clave)) return cache.get(clave);
    const resultado = fn(...args);
    cache.set(clave, resultado);
    return resultado;
  }

  decorada.limpiarCache = () => cache.clear();
  decorada.getCacheSize = () => cache.size;

  return decorada;
}

let llamadasReales = 0;
const calcularCostoso = conCache((n) => {
  llamadasReales++;
  return n * n; // Simula cálculo costoso
});

const r1 = calcularCostoso(5);  // Calcula
const r2 = calcularCostoso(5);  // Desde caché
const r3 = calcularCostoso(3);  // Calcula
const r4 = calcularCostoso(3);  // Desde caché

const llamadasRealesTotales = llamadasReales; // Solo 2 (5 y 3)
const cacheSize = calcularCostoso.getCacheSize(); // 2

console.log(r1, r2, r3, r4);
console.log('Llamadas reales:', llamadasRealesTotales, '| Caché:', cacheSize);

function conLog(fn, nombre = fn.name) {
  const logs = [];
  function decorada(...args) {
    logs.push(`→ ${nombre}(${JSON.stringify(args)})`);
    const resultado = fn(...args);
    // Si es Promise, espera para loguear la salida
    if (resultado instanceof Promise) {
      return resultado.then(r => {
        logs.push(`← ${nombre} = ${JSON.stringify(r)}`);
        return r;
      }).catch(e => {
        logs.push(`✗ ${nombre} error: ${e.message}`);
        throw e;
      });
    }
    logs.push(`← ${nombre} = ${JSON.stringify(resultado)}`);
    return resultado;
  }
  decorada.logs = logs;
  return decorada;
}

function conTimeout(fn, ms) {
  return function(...args) {
    return Promise.race([
      Promise.resolve(fn(...args)),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error('Timeout')), ms)
      ),
    ]);
  };
}

function conReintentos(fn, n) {
  return async function(...args) {
    for (let i = 0; i < n; i++) {
      try {
        return await fn(...args);
      } catch (e) {
        if (i === n - 1) throw e;
      }
    }
  };
}

// Simula una API que falla las primeras 2 veces
let intentos = 0;
async function llamarAPI(url) {
  intentos++;
  if (intentos < 3) throw new Error(`Fallo intento ${intentos}`);
  return { status: 200, data: url + '-ok' };
}

const apiFinal = conReintentos(conTimeout(llamarAPI, 1000), 3);

const resultado = await apiFinal('https://api.test.com');
const exitoso = resultado.data.includes('ok');
const intentosTotales = intentos;

console.log('Resultado:', resultado);
console.log('Exitoso:', exitoso, '| Intentos:', intentosTotales);
